sourceControls.terminal_revisit_canonical_controls.lp:
require open emdash.emdash3_2;

assert [K : Cat] (x y : τ (Obj K)) ⊢
  @homd_tgt_func K (@Const_catd K Terminal_cat) (@Const_catd K Terminal_cat)
    (@id_funcd K (@Const_catd K Terminal_cat)) x Terminal_obj y
  ≡ @Obj_func (Homd_index_cat (Hom_cat K x y))
      (fapp0 (Homd_index_include_func (Hom_cat K x y)) (@Terminal_catd (Op_cat (Hom_cat K x y))));

assert [B : Cat] (P : τ (Hom Homd_coeff_cat Terminal_cat B)) ⊢
 @comp_fapp0 Homd_coeff_cat Terminal_cat Terminal_cat B P
  (@Homd_coeff_conjoint Terminal_cat Terminal_cat (@id_func Terminal_cat)) ≡ P;
assert [A : Cat] (P : τ (Hom Homd_coeff_cat A Terminal_cat)) ⊢
 @comp_fapp0 Homd_coeff_cat A Terminal_cat Terminal_cat
  (@Homd_coeff_conjoint Terminal_cat Terminal_cat (@id_func Terminal_cat)) P ≡ P;

assert [A B : Cat] (F : τ (Functor A B)) ⊢
 @comp_fapp0 Homd_coeff_cat Terminal_cat B A
  (@Homd_coeff_conjoint B A F)
  (@Homd_coeff_conjoint Terminal_cat B (@Const_func B Terminal_cat Terminal_obj))
 ≡ @Homd_coeff_conjoint Terminal_cat A
     (@comp_cat_fapp0 A B Terminal_cat (@Const_func B Terminal_cat Terminal_obj) F);

assert [C I : Cat] (G : τ (Functor Terminal_cat C)) ⊢
 @comp_fapp0 Homd_coeff_cat C Terminal_cat I
  (@Homd_coeff_conjoint Terminal_cat I (@Const_func I Terminal_cat Terminal_obj))
  (@Homd_coeff_conjoint C Terminal_cat G)
 ≡ @Homd_coeff_conjoint C I
     (@comp_cat_fapp0 I Terminal_cat C G (@Const_func I Terminal_cat Terminal_obj));

assertnot [I : Cat] (u : τ (Obj Terminal_cat)) ⊢
 @Homd_coeff_conjoint Terminal_cat I (@Const_func I Terminal_cat u)
 ≡ @Const_func Terminal_cat (Homd_index_cat I) (@Const_func I (Op_cat Cat_cart) Terminal_cat);

assert [I : Cat] (u v : τ (Obj Terminal_cat)) ⊢
 @fapp1_func Terminal_cat (Homd_index_cat I)
  (@Homd_coeff_conjoint Terminal_cat I (@Const_func I Terminal_cat Terminal_obj)) u v
 ≡ @fapp1_func Terminal_cat (Homd_index_cat I)
  (@Homd_coeff_conjoint_body Terminal_cat I (@Const_func I Terminal_cat Terminal_obj)) u v;

sourceControls.terminal_projection_normalforms.lp:
require open emdash.emdash3_2;

compute λ (I : Cat) (F : τ (Functor I Terminal_cat))
 (u v : τ (Obj Terminal_cat)) (h : τ (Hom Terminal_cat u v))
 (i : τ (Obj I)) ,
@tapp0_fapp0 (Op_cat I) Cat_cart
  (@hom_con Terminal_cat u I F) (@hom_con Terminal_cat v I F) i
  (@strict_transfor (Op_cat I) Cat_cart
    (@hom_con Terminal_cat u I F) (@hom_con Terminal_cat v I F)
    (@hom_con_int_postcomp_func Terminal_cat I F u v h));

compute λ (I : Cat) (F : τ (Functor I Terminal_cat))
 (u v : τ (Obj Terminal_cat)) (h : τ (Hom Terminal_cat u v))
 (i : τ (Obj I)) ,
@hom_postcomp_func Terminal_cat Terminal_cat (@id_func Terminal_cat)
  (@fapp0 I Terminal_cat F i) u v h;

sourceControls.terminal_unit_regression.lp:
require open emdash.emdash3_2;

// Existing represented right-unit computation, with a neutral terminal arrow.
assert (h : τ (Hom Terminal_cat Terminal_obj Terminal_obj)) ⊢
 @hom_postcomp_fapp0 Terminal_cat Terminal_cat (@id_func Terminal_cat)
   Terminal_obj Terminal_obj Terminal_obj h (@id Terminal_cat Terminal_obj)
 ≡ h;

sourceControls.terminal_inverse_regression.lp:
require open emdash.emdash3_2;

// Preserve the existing cuts on actual inverse data in the terminal fibre.
assert (i : τ (@DefIso Terminal_cat Terminal_obj Terminal_obj)) ⊢
 @hom_postcomp_fapp0 Terminal_cat Terminal_cat (@id_func Terminal_cat)
   Terminal_obj Terminal_obj Terminal_obj
   (@defiso_from Terminal_cat Terminal_obj Terminal_obj i)
   (@defiso_to Terminal_cat Terminal_obj Terminal_obj i)
 ≡ @id Terminal_cat Terminal_obj;

